INSERT INTO `email_templates` (`id`, `ids`, `name`, `subject`, `status`, `content`, `created`, `changed`) VALUES
(30, '7b628514-5768-41bd-a3b7-6d2717378eb5', 'new_ticket_via_contact_form_to_admin', '{{website_name}} - New Ticket', 1, '<p>Hello Admin,</p>\r\n<p>A new ticket has been successfully submitted via the Contact Us form. Here are the details:</p>\r\n<ul>\r\n<li><strong>Subject:</strong> {{subject}}</li>\r\n<li><strong>Customer email:</strong> {{customer_email}}</li>\r\n<li><strong>Ticket ID:</strong> {{ticket_id}}</li>\r\n</ul>\r\n<p>Thank you for your prompt attention to this matter!</p>\r\n<p>Best Regards, <br />{{website_name}}</p>', '2025-02-21 14:33:54', '2025-02-21 07:46:25'),
(28, 'a5f733f0-11c1-4050-8f23-fba362224407', 'new_order_notification_to_customer', '{{website_name}} - Your Order Has Been Successfully Placed! ', 1, '<p>Dear Customer,</p>\r\n<p>Thank you for your purchase at <strong>{{website_name}}</strong>!</p>\r\n<p>Your order has been successfully placed. Below is the delivery information for your order:</p>\r\n<ul>\r\n<li><strong>Email:</strong> {{customer_email}}</li>\r\n<li><strong>Order ID:</strong> {{client_order_id}}</li>\r\n<li><strong>Amount:</strong> {{amount}}</li>\r\n<li><strong>Package:</strong> {{quantity}} - <span>{{service_name}}</span></li>\r\n<li><strong>Track your order:</strong> <a href=\"{{track_order_link}}\" target=\"_blank\" rel=\"noopener\">{{track_order_link}}</a></li>\r\n</ul>\r\n<p>It has been a pleasure doing business with you. We wish you all the best with your order!</p>\r\n<p>Thanks and Best Regards,<br /><strong>{{website_name}}</strong></p>', '2025-02-11 16:11:16', '2025-02-21 07:46:25'),
(29, '566d57f7-676a-4250-8501-df4e3a342fa6', 'new_order_notification_to_admin', '{{website_name}} - New order successfully!', 1, '<p>Hello Admin,</p>\r\n<p>A new order has been placed successfully on <strong>{{website_name}}</strong>. Here are the details:</p>\r\n<ul>\r\n<li><strong>Email:</strong> {{customer_email}}</li>\r\n<li><strong>Order ID:</strong> {{client_order_id}}</li>\r\n<li><strong>Amount:</strong> {{amount}}</li>\r\n<li><strong>Package:</strong> {{quantity}} - {{service_name}}</li>\r\n</ul>\r\n<p>Thank you for managing the orders!</p>\r\n<p>Best Regards,<br />{{website_name}}</p>', '2025-02-11 16:11:16', '2025-02-21 07:46:25');

