--
-- Structure de la table `orders`
--

CREATE TABLE `orders` (
  `id` int(11) NOT NULL,
  `ids` mediumtext DEFAULT NULL,
  `client_order_id` varchar(100) DEFAULT NULL,
  `uid` varchar(191) DEFAULT NULL,
  `type` enum('direct','api') NOT NULL DEFAULT 'direct',
  `cate_id` varchar(191) DEFAULT NULL,
  `service_id` varchar(191) DEFAULT NULL,
  `service_type` varchar(50) DEFAULT 'default',
  `api_provider_id` int(11) DEFAULT NULL,
  `api_service_id` varchar(200) DEFAULT NULL,
  `api_order_id` int(11) DEFAULT 0,
  `order_details` text DEFAULT NULL,
  `api_charge` double NOT NULL,
  `status` enum('active','completed','processing','inprogress','pending','partial','canceled','refunded','awaiting','error') DEFAULT 'pending',
  `charge` decimal(15,4) DEFAULT NULL,
  `formal_charge` decimal(15,4) DEFAULT NULL,
  `profit` decimal(15,4) DEFAULT NULL,
  `link` varchar(191) DEFAULT NULL,
  `quantity` varchar(191) DEFAULT NULL,
  `start_counter` varchar(191) DEFAULT '0',
  `remains` varchar(191) DEFAULT '0',
  `note` text DEFAULT NULL,
  `ip_address` varchar(100) NOT NULL DEFAULT '',
  `last_check` datetime DEFAULT NULL,
  `changed` datetime DEFAULT NULL,
  `created` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `pages`
--

CREATE TABLE `pages` (
  `id` int(11) NOT NULL,
  `ids` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `url_slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `page_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'default',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0:Disaled,1:Published,2:Pending',
  `is_core_page` tinyint(1) DEFAULT 0 COMMENT 'Is core page: 1: Active, 0: Inactive',
  `options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created` datetime DEFAULT current_timestamp(),
  `changed` datetime DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

--
-- Déchargement des données de la table `pages`
--

