(23, '2e7dfad6-6ef5-420a-a1d9-988809b2b0a0', 13, 'Liên hệ', 'lien-he', 'vi', '{\"title\":\"\",\"keywords\":\"\",\"description\":\"\",\"image_url\":\"\",\"index\":\"index\"}', '{\"1\":{\"section_type\":\"contact_us_section\",\"fields\":{\"title\":\"Contact Us\",\"short_desc\":\"We would love to hear from you! Please fill out the form below and we will get back to you as soon as possible.\",\"image_position\":\"left\",\"image_url\":\"http:\\/\\/smmstore.test\\/code4\\/assets\\/themes\\/regular\\/img\\/home\\/boost-your-social-media-impact-with-expert-support.png\",\"information_status\":\"1\"}},\"2\":{\"section_type\":\"optional_content_section\",\"fields\":{\"content\":\"\"}}}', ''),
(24, '1e6b4aab-28f3-481d-a0f4-5e2cc7d1a4a8', 14, 'Reviews', 'reviews', 'en', '{\"title\":\"\",\"keywords\":\"\",\"description\":\"\",\"image_url\":\"\",\"index\":\"index\"}', '{\"1\":{\"section_type\":\"header_section\",\"fields\":{\"left_span_text_in_title\":\"SmartStore\",\"title\":\"Promotion Service\",\"short_desc\":\"Read what our customers have to say about our top-notch promotion services, designed to enhance your social media presence with effective and authentic solutions.\",\"background_image_url\":\"https:\\/\\/smartpanel.dev\\/assets\\/themes\\/regular\\/img\\/home\\/header-top-bg.png\",\"button_status\":\"0\",\"button_name\":\"Get Started\",\"button_url\":\"buy-instagram-likes\"}},\"2\":{\"section_type\":\"reviews_section\",\"fields\":{\"title\":\"What do our customers say?\",\"short_desc\":\"Customer reviews\",\"btn_add_review_status\":\"1\",\"btn_load_more_status\":\"1\"}}}', ''),
(25, 'fe15e45b-ef83-48f5-9c3c-2f38afbeb922', 15, 'FAQS', 'faqs', 'en', '{\"title\":\"\",\"keywords\":\"\",\"description\":\"\",\"image_url\":\"\",\"index\":\"index\"}', '{\"1\":{\"section_type\":\"faqs_section\",\"fields\":{\"title\":\"Frequently Asked Questions\",\"short_desc\":\"Get answers to your queries about our likes and followers services.\",\"layout_type\":\"left\",\"features\":[{\"title\":\"How do I place an order?\",\"content\":\"To place an order, simply choose the service you want, select the package that fits your needs, and proceed to checkout. You\'ll receive instant confirmation once your order is placed.\"},{\"title\":\"What payment methods do you accept?\",\"content\":\"We accept various payment methods including credit cards, PayPal, and other secure payment gateways. Your payment information is always protected.\"},{\"title\":\"How long will it take to see results?\",\"content\":\"Depending on the package you choose, results can typically be seen within a few hours to a few days. Our services are designed to provide quick and effective results.\"},{\"title\":\"Can I use your services for multiple accounts?\",\"content\":\"Yes, you can use our services for multiple accounts. Just make sure to place separate orders for each account to ensure accurate delivery of likes and followers.\"}]}}}', '');

